const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Lake Urmia geometry
  const lakeUrmia = ee.Geometry.Point([45.5, 37.5]).buffer(20000);

  // 2. Define dates
  const date1 = '2016-04-23';
  const date2 = '2016-07-18';

  // 3. Function to mask clouds for Sentinel-2
  function maskS2clouds(image) {
    const qa = image.select('QA60');
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
        .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask);
  }

  // 4. Try to get Sentinel-2 images
  let col1 = ee.ImageCollection('COPERNICUS/S2_HARMONIZED')
    .filterBounds(lakeUrmia)
    .filterDate(date1, ee.Date(date1).advance(1, 'day'))
    .map(maskS2clouds);

  let col2 = ee.ImageCollection('COPERNICUS/S2_HARMONIZED')
    .filterBounds(lakeUrmia)
    .filterDate(date2, ee.Date(date2).advance(1, 'day'))
    .map(maskS2clouds);

  const size1 = col1.size().getInfo();
  const size2 = col2.size().getInfo();

  console.log(`April 23 images: ${size1}`);
  console.log(`July 18 images: ${size2}`);

  // 5. Fallback to Landsat 8 if needed
  if (size1 === 0 || size2 === 0) {
    console.log('Trying Landsat 8 fallback...');

    function maskL8clouds(image) {
      const qa = image.select('QA_PIXEL');
      const cloudMask = qa.bitwiseAnd(1 << 3).eq(0);
      return image.updateMask(cloudMask);
    }

    col1 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
      .filterBounds(lakeUrmia)
      .filterDate(date1, ee.Date(date1).advance(7, 'day'))
      .map(maskL8clouds);

    col2 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
      .filterBounds(lakeUrmia)
      .filterDate(date2, ee.Date(date2).advance(7, 'day'))
      .map(maskL8clouds);

    const ls1 = col1.size().getInfo();
    const ls2 = col2.size().getInfo();

    console.log(`Landsat Apr images: ${ls1}, Jul images: ${ls2}`);

    if (ls1 === 0 || ls2 === 0) {
      console.log('No images found for one or both dates.');
      console.log('<answer>C1</answer>');
      return;
    }
  }

  // 6. Get median composites
  const img1 = col1.median();
  const img2 = col2.median();

  // 7. Calculate redness (Red band reflectance)
  const redBand = size1 > 0 ? 'B4' : 'SR_B4';

  // 8. Calculate mean red reflectance with pixel count
  const stats1 = img1.select(redBand).reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: lakeUrmia,
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const stats2 = img2.select(redBand).reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: lakeUrmia,
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const red1 = stats1.mean || stats1[redBand + '_mean'];
  const red2 = stats2.mean || stats2[redBand + '_mean'];
  const count1 = stats1.count || stats1[redBand + '_count'];
  const count2 = stats2.count || stats2[redBand + '_count'];

  console.log(`April 23 Red: ${red1}, Pixels: ${count1}`);
  console.log(`July 18 Red: ${red2}, Pixels: ${count2}`);

  // 9. Validation
  if (!count1 || !count2 || count1 === 0 || count2 === 0) {
    console.log('No valid pixels after masking.');
    console.log('<answer>C2</answer>');
    return;
  }

  if (red1 === null || red2 === null || isNaN(red1) || isNaN(red2)) {
    console.log('Calculation failed - invalid values.');
    console.log('<answer>C3</answer>');
    return;
  }

  // 10. Compare redness
  if (red2 < red1) {
    console.log('July shows lower redness than April.');
    console.log('<answer>A</answer>');
  } else {
    console.log('July does not show lower redness than April.');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
